    """Remove ANSI escape sequences from ``text``."""
    return _ANSI_RE.sub("", text)


def _color_code(color, background=False):
    base = 40 if background else 30
    if isinstance(color, str):
        if color == "reset":
            return "49" if background else "39"
        if color not in _COLORS:
            raise ValueError(f"Unknown color '{color}'.")
        code = _COLORS[color]
        if background:
            code += 10
        return str(code)
    if isinstance(color, bool):
        raise TypeError("Color must be a name, an int, or an RGB sequence.")
    if isinstance(color, int):
        if not 0 <= color <= 255:
            raise ValueError("Color index must be in 0-255.")
        return f"{base + 8}8;5;{color}"
    if isinstance(color, (list, tuple)) and len(color) == 3:
        for c in color:
            if not isinstance(c, int) or not 0 <= c <= 255:
                raise ValueError("RGB components must be integers in 0-255.")
        return f"{base + 8}8;2;{color[0]};{color[1]};{color[2]}"
    raise ValueError(f"Invalid color: {color!r}")


def style(text, fg=None, bg=None, bold=None, dim=None, underline=None, overline=None,
          italic=None, blink=None, reverse=None, strikethrough=None, reset=True):
    """Wrap ``text`` in ANSI SGR sequences."""
    codes = []
    if fg is not None:
        codes.append(_color_code(fg))
    if bg is not None:
        codes.append(_color_code(bg, background=True))
    switches = {
        "bold": bold, "dim": dim, "underline": underline, "overline": overline,
        "italic": italic, "blink": blink, "reverse": reverse, "strikethrough": strikethrough,
    }
    for name, on in switches.items():
        if on is not None:
            codes.append(str(_STYLE_CODES[name]) if on else str(_STYLE_CODES[name] + 20))
            if name == "overline" and not on:
                codes[-1] = "55"
    if not codes:
        return text
    prefix = f"\033[{';'.join(codes)}m"
    return prefix + text + ("\033[0m" if reset else "")


