        if not self.dir_okay and os.path.isdir(rv):
            self.fail(f"'{raw}' is a directory.", param, ctx)
        if self.readable and not os.access(rv, os.R_OK):
            self.fail(f"'{raw}' is not readable.", param, ctx)
        if self.writable and not os.access(rv, os.W_OK):
            self.fail(f"'{raw}' is not writable.", param, ctx)
        if self.executable and not os.access(rv, os.X_OK):
            self.fail(f"'{raw}' is not executable.", param, ctx)
