    def convert(self, value, param=None, ctx=None):
        v = super().convert(value, param, ctx)
        if self.min is not None and v < self.min:
            if self.clamp:
                return float(self.min)
            self.fail(f"{v} is not in the valid range.", param, ctx)
        if self.max is not None and v > self.max:
            if self.clamp:
                return float(self.max)
            self.fail(f"{v} is not in the valid range.", param, ctx)
        return v


class Tuple(ParamType):
    name = "tuple"
    is_composite = True

    def __init__(self, types):
        self.types = [convert_type(t) for t in types]

    @property
    def arity(self):
        return len(self.types)

    def convert(self, value, param=None, ctx=None):
        if len(value) != len(self.types):
            self.fail(f"expected {len(self.types)} values, got {len(value)}.", param, ctx)
        return tuple(t.convert(v, param, ctx) for t, v in zip(self.types, value))


def open_stream(filename, mode="r", encoding=None, errors="strict", lazy=False, atomic=False):
    """Open a real file, or return a standard stream for ``-``."""
    if filename == "-":
        if "r" in mode:
            stream = sys.stdin
        else:
            stream = sys.stdout
        if "b" in mode:
            return getattr(stream, "buffer", stream)
        return stream
    if lazy:
        return LazyFile(filename, mode, encoding, errors, atomic)
    return _open_real(filename, mode, encoding, errors, atomic)


def _open_real(filename, mode, encoding, errors, atomic):
    if atomic and "w" in mode:
        return AtomicFile(filename, mode, encoding, errors)
    kwargs = {} if "b" in mode else {"encoding": encoding, "errors": errors}
    return open(filename, mode, **kwargs)


class AtomicFile(io.IOBase):
    """Writes to a sibling temp file and replaces the target on close."""

    def __init__(self, filename, mode, encoding, errors):
        self._target = os.fspath(filename)
        self._tmp = self._target + ".tmp-optlyn"
        kwargs = {} if "b" in mode else {"encoding": encoding, "errors": errors}
        self._f = open(self._tmp, mode, **kwargs)

    def write(self, data):
        return self._f.write(data)

    def flush(self):
        self._f.flush()

    def close(self):
        if self.closed:
            return
        self._f.close()
        os.replace(self._tmp, self._target)
        super().close()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()


class LazyFile:
    """Defers opening a write-mode file until first I/O."""

    def __init__(self, filename, mode, encoding, errors, atomic):
        self._args = (filename, mode, encoding, errors, atomic)
        self._f = None

    def _real(self):
        if self._f is None:
            self._f = _open_real(*self._args)
        return self._f

    def __getattr__(self, name):
        return getattr(self._real(), name)

    def write(self, data):
        return self._real().write(data)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        if self._f is not None:
            self._f.close()


class File(ParamType):
    name = "filename"

    def __init__(self, mode="r", encoding=None, errors="strict", lazy=None, atomic=False):
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.atomic = atomic
        if lazy is None:
            lazy = "r" not in mode
        self.lazy = lazy

    def convert(self, value, param=None, ctx=None):
        if hasattr(value, "read") or hasattr(value, "write"):
            return value
        if value == "-":
            return open_stream("-", self.mode, self.encoding, self.errors)
        try:
            if self.lazy:
                return LazyFile(value, self.mode, self.encoding, self.errors, self.atomic)
            return _open_real(value, self.mode, self.encoding, self.errors, self.atomic)
        except OSError as e:
            self.fail(f"'{value}': {e.strerror or e}", param, ctx)


class Path(ParamType):
    name = "path"

    def __init__(self, exists=False, file_okay=True, dir_okay=True, writable=False,
                 readable=True, resolve_path=False, allow_dash=False, path_type=None,
                 executable=False):
        self.exists = exists
        self.file_okay = file_okay
        self.dir_okay = dir_okay
        self.writable = writable
        self.readable = readable
        self.resolve_path = resolve_path
        self.allow_dash = allow_dash
        self.path_type = path_type
        self.executable = executable

    def convert(self, value, param=None, ctx=None):
        raw = os.fspath(value)
        if self.allow_dash and raw == "-":
            return self._out("-")
        rv = raw
        if self.resolve_path:
            rv = os.path.realpath(rv)
            if not os.path.isabs(rv):
                rv = os.path.abspath(rv)
        if not os.path.exists(rv):
            if self.exists:
                self.fail(f"'{raw}' does not exist.", param, ctx)
            return self._out(rv)
        if not self.file_okay and os.path.isfile(rv):
            self.fail(f"'{raw}' is a file.", param, ctx)
        if not self.dir_okay and os.path.isdir(rv):
            self.fail(f"'{raw}' is a directory.", param, ctx)
        if self.readable and not os.access(rv, os.R_OK):
            self.fail(f"'{raw}' is not readable.", param, ctx)
        if self.writable and not os.access(rv, os.W_OK):
            self.fail(f"'{raw}' is not writable.", param, ctx)
        if self.executable and not os.access(rv, os.X_OK):
            self.fail(f"'{raw}' is not executable.", param, ctx)
        return self._out(rv)

    def _out(self, p):
        if self.path_type is _PathLib:
            return _PathLib(p)
        if self.path_type is str or self.path_type is None:
            return p
        return self.path_type(p)

    def shell_complete(self, ctx, param, incomplete):
        return []


_BUILTIN = {
    str: STRING,
    int: INT,
    float: FLOAT,
    bool: BOOL,
    _uuid.UUID: UUID,
}


def convert_type(ty, default=None):
    """Turn a type spec (instance, class, callable, tuple of types, or None) into a ParamType."""
    if isinstance(ty, ParamType):
        return ty
    if isinstance(ty, tuple):
        return Tuple(ty)
    if isinstance(ty, type) and issubclass(ty, ParamType):
        return ty()
    if ty is None and default is not None:
        if isinstance(default, bool):
            return BOOL
        if isinstance(default, int):
            return INT
        if isinstance(default, float):
            return FLOAT
        if isinstance(default, tuple):
            return Tuple([type(v) for v in default])
        if isinstance(default, (list, tuple)) and default:
            return convert_type(None, default[0])
        return STRING
    if ty is None:
        return STRING
    if ty in _BUILTIN:
        return _BUILTIN[ty]
    if callable(ty):
        return FuncType(ty)
    raise TypeError(f"Unsupported type: {ty!r}")


class FuncType(ParamType):
    """Wraps a conversion function ``f(token) -> value`` that refuses by raising ValueError."""

    def __init__(self, func):
        self.func = func
        self.name = getattr(func, "__name__", "text")

    def convert(self, value, param=None, ctx=None):
        if not isinstance(value, str):
            return value
        try:
            return self.func(value)
        except BadParameter:
            raise
        except ValueError as e:
            self.fail(str(e) or f"{value!r} is invalid", param, ctx)

