"""POSIX-style token parsing for one command invocation.

The parser walks the token list once. It records command-line values per
parameter, collects positional tokens, and, for groups, stops at the
subcommand name so the rest of the tokens go to the child.
"""

from .exceptions import BadParameter, Exit, MissingParameter, NoSuchOption, UsageError
from .parameters import Argument, Option, PREFIX_CHARS


class ParseResult:
    def __init__(self):
        self.raw = {}              # Parameter -> command-line value
        self.positional = []       # list of (token, after_double_dash)
        self.leftover = []         # tokens not bound to arguments
        self.subcommand = None     # name of the subcommand, for groups
        self.subargs = []          # tokens for the subcommand
        self.used_deprecated = []  # parameters the user actually supplied


class Parser:
    def __init__(self, command, ctx, *, is_group=False, interspersed=True,
                 ignore_unknown=False, allow_extra=False):
        self.command = command
        self.ctx = ctx
        self.is_group = is_group
        self.interspersed = interspersed
        self.ignore_unknown = ignore_unknown
        self.allow_extra = allow_extra
        self.res = ParseResult()
        self.by_name = {}
        for opt in command.options:
            for name in opt.all_names:
                self.by_name[name] = opt
        self.prefixes = {"-"} | {n[0] for n in self.by_name}
        self.help_names = list(ctx.help_option_names) if command.add_help_option else []

    # Token classification -------------------------------------------------

    def _is_option_like(self, tok):
        return len(tok) > 1 and tok[0] in self.prefixes

    # Entry point ----------------------------------------------------------

    def parse(self, tokens):
        res = self.res
        arguments = self.command.arguments
        stopped = False
        seen_positional = False
        i = 0
        n = len(tokens)
        while i < n:
            tok = tokens[i]
            if not stopped and tok == "--":
                stopped = True
                i += 1
                continue
            if self.is_group and seen_positional and not self.interspersed:
                # Group options end at the subcommand name; subcommand gets the rest.
                pass
            if not stopped and self._is_option_like(tok) and not (
                    seen_positional and not self.interspersed):
                consumed = self._handle_option(tokens, i)
                if consumed is not None:
                    i += consumed
                    continue
            # Positional token.
            seen_positional = True
            if self.is_group:
                if self._group_args_full():
                    res.subcommand = tok
                    res.subargs = list(tokens[i + 1:])
                    if self.interspersed or not self.command.mixing_allowed:
                        self._finish_group_mixed()
                    return res
                res.positional.append((tok, stopped))
                i += 1
                continue
            res.positional.append((tok, stopped))
            i += 1
        if self.is_group:
            if not self._group_args_full():
                # Group arguments were not all supplied; bind what we have.
                self._bind_arguments()
            else:
                self._bind_arguments()
            return res
        self._bind_arguments()
        return res

    def _finish_group_mixed(self):
        pass

    # Options ----------------------------------------------------------------

    def _handle_option(self, tokens, i):
        tok = tokens[i]
        if tok[1] in self.prefixes and len(tok) > 2 or tok[:2] in ("--", "//", "++"):
            return self._handle_long(tokens, i)
        return self._handle_short(tokens, i)

    def _handle_long(self, tokens, i):
        tok = tokens[i]
        name, eq, inline = tok.partition("=")
        opt = self.by_name.get(name)
        if opt is None:
            if name in self.help_names:
                self._show_help()
            if self.ignore_unknown:
                return None
            raise NoSuchOption(name, ctx=self.ctx)
        return self._take(opt, name, tokens, i, inline if eq else None, 1)

    def _handle_short(self, tokens, i):
        tok = tokens[i]
        prefix = tok[0]
        chars = tok[1:]
        for k, ch in enumerate(chars):
            name = prefix + ch
            opt = self.by_name.get(name)
            if opt is None:
                if name in self.help_names:
                    self._show_help()
                if self.ignore_unknown:
                    if k == 0:
                        return None
                    self.res.positional.append((prefix + chars[k:], False))
                    return 1
                raise NoSuchOption(name, ctx=self.ctx)
            if opt.takes_value:
                rest = chars[k + 1:]
                if rest:
                    return self._take(opt, name, tokens, i, rest, 1)
                return self._take(opt, name, tokens, i, None, 1)
            self._record_flag(opt, name)
        return 1

    def _take(self, opt, name, tokens, i, inline, consumed):
        """Consume the value tokens for ``opt`` (if any) and record the occurrence."""
        if not opt.takes_value:
            if inline is not None:
                raise UsageError(f"Option {name} does not take a value.", ctx=self.ctx)
            self._record_flag(opt, name)
            return consumed
        if opt.is_flag or opt.count:
            self._record_flag(opt, name)
            return consumed
        values = []
        if inline is not None:
            values.append(inline)
        need = opt.nargs - len(values)
        j = i + consumed
        while need > 0 and j < len(tokens):
            values.append(tokens[j])
            j += 1
            need -= 1
        if need > 0:
            if opt.prompt is not None and not values:
                # Flag present without a value and prompting is enabled: the prompt runs later.
                self._record(opt, name, PROMPT)
                return consumed
            raise BadParameter(f"Option {name} requires an argument.", ctx=self.ctx,
                               param=opt)
        self._note_deprecated(opt)
        value = values[0] if opt.nargs == 1 else tuple(values)
        if opt.multiple:
            self.res.raw.setdefault(opt, []).append(value)
        else:
            self.res.raw[opt] = value
        return (j - i)

    def _record_flag(self, opt, name):
        self._note_deprecated(opt)
        if opt.count:
            self.res.raw[opt] = self.res.raw.get(opt, 0) + 1
        elif opt.multiple:
            self.res.raw.setdefault(opt, []).append(opt.flag_value_for(name))
        else:
            self.res.raw[opt] = opt.flag_value_for(name)

    def _record(self, opt, name, value):
        self.res.raw[opt] = value

    def _note_deprecated(self, param):
        if param.deprecated and param not in self.res.used_deprecated:
            self.res.used_deprecated.append(param)

    def _show_help(self):
        from .help import echo_help

        echo_help(self.ctx)
        raise Exit(0)

    # Arguments --------------------------------------------------------------

    def _group_args_full(self):
        """True when every group argument has enough positional tokens bound."""
        needed = sum(a.nargs for a in self.command.arguments if not a.variadic)
        return len(self.res.positional) >= needed

    def _bind_arguments(self):
        res = self.res
        toks = res.positional
        idx = 0
        args = self.command.arguments
        for k, arg in enumerate(args):
            if arg.variadic:
                reserve = sum(a.nargs for a in args[k + 1:] if not a.variadic)
                take = max(0, len(toks) - idx - reserve)
                if take:
                    res.raw[arg] = tuple(t for t, _ in toks[idx: idx + take])
                    idx += take
                continue
            remaining = len(toks) - idx
            if remaining == 0:
                if arg.required:
                    raise MissingParameter(f"Missing argument '{arg.name}'.",
                                           ctx=self.ctx, param=arg,
                                           param_hint=arg.name.upper())
                continue
            if remaining < arg.nargs:
                raise BadParameter(f"Argument '{arg.name}' requires {arg.nargs} values.",
                                   ctx=self.ctx, param=arg)
            chunk = [t for t, _ in toks[idx: idx + arg.nargs]]
            idx += arg.nargs
            if arg.nargs == 1:
                res.raw[arg] = chunk[0]
            else:
                res.raw[arg] = tuple(chunk)
            self._note_deprecated(arg)
        for tok, after_dd in toks[idx:]:
            if self.allow_extra:
                if not after_dd and self._is_option_like(tok):
                    raise UsageError(f"No such option: {tok}", ctx=self.ctx)
                res.leftover.append(tok)
                continue
            raise UsageError(f"Got unexpected extra argument ({tok})", ctx=self.ctx)


class _Prompt:
    """Sentinel: a value that must come from an interactive prompt."""

    def __repr__(self):
        return "PROMPT"


PROMPT = _Prompt()

