"""POSIX-style token parsing for one command invocation.

The parser walks the token list once. It records command-line values per
parameter and collects positional tokens. For groups it stops at the
subcommand name, so the remaining tokens belong to the child.
"""

from .exceptions import BadParameter, Exit, MissingParameter, NoSuchOption, UsageError


class _Prompt:
    """Sentinel: the value must come from an interactive prompt."""

    def __repr__(self):
        return "PROMPT"


PROMPT = _Prompt()


class ParseResult:
    def __init__(self):
        self.raw = {}              # Parameter -> command-line value (or PROMPT)
        self.positional = []       # list of (token, after_double_dash)
        self.leftover = []         # tokens not bound to arguments
        self.subcommand = None     # subcommand name, for groups
        self.subargs = []          # tokens for the subcommand
        self.used_deprecated = []  # parameters the user actually supplied


class Parser:
    def __init__(self, command, ctx, *, is_group=False, interspersed=True,
                 ignore_unknown=False, allow_extra=False):
        self.command = command
        self.ctx = ctx
        self.is_group = is_group
        self.interspersed = interspersed
        self.ignore_unknown = ignore_unknown
        self.allow_extra = allow_extra
        self.res = ParseResult()
        self.by_name = {}
        for opt in command.options:
            for name in opt.all_names:
                self.by_name[name] = opt
        self.prefixes = {"-"} | {name[0] for name in self.by_name}
        self.help_names = list(ctx.help_option_names) if command.add_help_option else []

    def _is_option_like(self, tok):
        return len(tok) > 1 and tok[0] in self.prefixes

    # Entry point ------------------------------------------------------------

    def parse(self, tokens):
        res = self.res
        stopped = False
        i = 0
        n = len(tokens)
        while i < n:
            tok = tokens[i]
            if not stopped and tok == "--":
                stopped = True
                i += 1
                continue
            seen_positional = bool(res.positional)
            if not stopped and self._is_option_like(tok) and (
                    self.interspersed or not seen_positional):
                consumed = self._handle_option(tokens, i)
                if consumed is not None:
                    i += consumed
                    continue
            if self.is_group and self._group_args_full():
                # This token is the subcommand name; the rest belong to the child.
                self._bind_arguments()
                res.subcommand = tok
                res.subargs = list(tokens[i + 1:])
                return res
            res.positional.append((tok, stopped))
            i += 1
        self._bind_arguments()
        return res

    # Options ----------------------------------------------------------------

    def _handle_option(self, tokens, i):
        tok = tokens[i]
        if len(tok) > 2 and tok[1] == tok[0]:
            return self._handle_long(tokens, i)
        return self._handle_short(tokens, i)

    def _handle_long(self, tokens, i):
        tok = tokens[i]
        name, eq, inline = tok.partition("=")
        opt = self.by_name.get(name)
        if opt is None:
            if name in self.help_names:
                self._show_help()
            if self.ignore_unknown:
                return None
            raise NoSuchOption(name, ctx=self.ctx)
        return self._take(opt, name, tokens, i, inline if eq else None)

    def _handle_short(self, tokens, i):
        tok = tokens[i]
        prefix = tok[0]
        chars = tok[1:]
        for k, ch in enumerate(chars):
            name = prefix + ch
            opt = self.by_name.get(name)
            if opt is None:
                if name in self.help_names:
                    self._show_help()
                if self.ignore_unknown:
                    if k == 0:
                        return None
                    # Known flags before k were consumed; the unknown rest stays as a token.
