"""In-process runner for invoking commands in tests."""

import io
import os
import shutil
import sys
import tempfile
from contextlib import contextmanager


class Result:
    def __init__(self, runner_output, stdout_bytes, stderr_bytes, exit_code, exception, charset):
        self._combined = runner_output
        self.stdout_bytes = stdout_bytes
        self.stderr_bytes = stderr_bytes
        self.exit_code = exit_code
        self.exception = exception
        self._charset = charset

    @property
    def output(self):
        return self._combined.decode(self._charset, "replace")

    @property
    def stdout(self):
        return self.stdout_bytes.decode(self._charset, "replace")

    @property
    def stderr(self):
        return self.stderr_bytes.decode(self._charset, "replace")

    def __repr__(self):
        return f"<Result exit_code={self.exit_code}>"


class _CaptureBytes(io.BytesIO):
    """A BytesIO that also appends everything it receives to a shared combined buffer."""

    def __init__(self, combined):
        super().__init__()
        self._combined = combined

    def write(self, data):
        self._combined.write(data)
        return super().write(data)


class CliRunner:
    def __init__(self, charset="utf-8", env=None, echo_stdin=False, catch_exceptions=True,
                 capture="sys"):
        self.charset = charset
        self.env = dict(env or {})
        self.echo_stdin = echo_stdin
        self.catch_exceptions = catch_exceptions
        self.capture = capture

    @contextmanager
    def isolation(self, input=None, env=None):
        combined = io.BytesIO()
        out_b = _CaptureBytes(combined)
        err_b = _CaptureBytes(combined)
        if isinstance(input, str):
            input = input.encode(self.charset)
        in_b = io.BytesIO(input or b"")
        stdin = io.TextIOWrapper(in_b, encoding=self.charset)
        stdout = io.TextIOWrapper(out_b, encoding=self.charset, errors="replace",
                                  write_through=True)
        stderr = io.TextIOWrapper(err_b, encoding=self.charset, errors="replace",
                                  write_through=True)
        merged_env = dict(self.env)
        merged_env.update(env or {})
        saved_env = {}
        for key, value in merged_env.items():
            saved_env[key] = os.environ.get(key)
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = str(value)
        old = sys.stdin, sys.stdout, sys.stderr
        sys.stdin, sys.stdout, sys.stderr = stdin, stdout, stderr
        try:
            yield out_b, err_b, combined
        finally:
            sys.stdin, sys.stdout, sys.stderr = old
            stdout.flush()
            stderr.flush()
