import os

import pytest

from optlyn import (Abort, Choice, IntRange, argument, command, confirmation_option,
                    custom_version_option, group, option, pass_obj)
from optlyn.formatting import first_sentence, wrap_text
from optlyn.shell_completion import complete
from optlyn.testing import CliRunner
from optlyn.termui import style, unstyle


@pytest.fixture
def runner():
    return CliRunner()


def make_tool():
    @group()
    @option("--verbose", "-v", is_flag=True)
    def tool(verbose):
        """Top-level tool."""

    @tool.command()
    @argument("name")
    @option("--count", type=int, default=2)
    @option("--mode", type=Choice(["a", "b"]))
    def hello(name, count, mode):
        """Say hello. More text."""
        print("hello", name, count, mode, "verbose" if False else "")

    @tool.command(hidden=True)
    def secret():
        print("secret")

    return tool


def test_command_name_derivation():
    @command()
    def my_thing_command():
        pass

    assert my_thing_command.name == "my-thing"


def test_group_dispatch_and_defaults(runner):
    tool = make_tool()
    r = runner.invoke(tool, ["hello", "bob", "--count", "3", "--mode", "a"])
    assert r.exit_code == 0
    assert "hello bob 3 a" in r.output


def test_group_no_args_is_usage_failure(runner):
    r = runner.invoke(make_tool(), [])
    assert r.exit_code == 2
    assert "Commands:" in r.stderr


def test_help_is_success_and_skips_callback(runner):
    tool = make_tool()
    r = runner.invoke(tool, ["hello", "--help"])
    assert r.exit_code == 0
